# Try using pysat
from pysat.solvers import Glucose3
from pysat.card import *

n = 24

# Encode as SAT
# Variables:
# p_i_v: position i has value v (i in 0..23, v in 0..23)
# d_i_d: difference at position i is d (i in 0..22, d in 1..23)

# p_i_v = (i * n + v + 1)  for i in 0..n-1, v in 0..n-1
# d_i_d = (n*n + i*(n-1) + d) for i in 0..n-2, d in 1..n-1

def p_var(i, v):
    return i * n + v + 1

def d_var(i, d):
    return n * n + i * (n - 1) + d

clauses = []

# Each position has exactly one value
for i in range(n):
    # At least one
    clauses.append([p_var(i, v) for v in range(n)])
    # At most one
    for v1 in range(n):
        for v2 in range(v1+1, n):
            clauses.append([-p_var(i, v1), -p_var(i, v2)])

# Each value appears exactly once
for v in range(n):
    clauses.append([p_var(i, v) for i in range(n)])
    for i1 in range(n):
        for i2 in range(i1+1, n):
            clauses.append([-p_var(i1, v), -p_var(i2, v)])

# Each difference position has exactly one difference value
for i in range(n-1):
    clauses.append([d_var(i, d) for d in range(1, n)])
    for d1 in range(1, n):
        for d2 in range(d1+1, n):
            clauses.append([-d_var(i, d1), -d_var(i, d2)])

# Each difference value appears exactly once
for d in range(1, n):
    clauses.append([d_var(i, d) for i in range(n-1)])
    for i1 in range(n-1):
        for i2 in range(i1+1, n-1):
            clauses.append([-d_var(i1, d), -d_var(i2, d)])

# Link P and D: if P[i]=v1 and P[i+1]=v2, then D[i]=|v1-v2|
for i in range(n-1):
    for v1 in range(n):
        for v2 in range(n):
            if v1 == v2:
                continue
            diff = abs(v1 - v2)
            # p_i_v1 AND p_{i+1}_v2 => d_i_diff
            clauses.append([-p_var(i, v1), -p_var(i+1, v2), d_var(i, diff)])

# Fix P[0] = 0
clauses.append([p_var(0, 0)])

print(f"Variables: {n*n + (n-1)*(n-1)}")
print(f"Clauses: {len(clauses)}")

solver = Glucose3()
for c in clauses:
    solver.add_clause(c)

import time
start = time.time()
print("Solving...")
result = solver.solve()
elapsed = time.time() - start
print(f"Time: {elapsed:.2f}s, Result: {result}")

if result:
    model = solver.get_model()
    solution = []
    for i in range(n):
        for v in range(n):
            if model[p_var(i, v) - 1] > 0:
                solution.append(v)
                break
    print(f"Solution: {solution}")
    diffs = [abs(solution[i+1] - solution[i]) for i in range(n-1)]
    print(f"Diffs sorted: {sorted(diffs)}")
    print(f"Valid: {sorted(solution) == list(range(n)) and sorted(diffs) == list(range(1, n))}")
else:
    print("UNSATISFIABLE")

solver.delete()
